function OverseaClubBossMainDialog:InitNodeEnv()
    if not isNull(self.RankNode) then
        local env = CfUtils.GetLuaScr(self.RankNode.gameObject,"Game.UI.Club.Boss.Cell.OverseaClubBossRankNode")
        if env then
            env:SetCheckCallBack(Bind(self,self.OnBossRankClick))
           self.rankNodeEnv = env
        end
    end

    if not isNull(self.RewardNode) then
        local env = CfUtils.GetLuaScr(self.RewardNode.gameObject,"Game.UI.Club.Boss.Cell.OverseaClubBossRewardNode")
        if env then
            self.rewardNodeEnv = env
        end
    end

    if not isNull(self.RecordNode) then
        local env = CfUtils.GetLuaScr(self.RecordNode.gameObject,"Game.UI.Club.Boss.Cell.OverseaClubBossRecordNode")
        if env then
            self.recordNodeEnv = env
        end
    end

    -- init chatNode
    ---@type OverseaChatButtonNode
    local chatButtonNode = CfUtils.GetLuaScr(self.OverseaChatBtnNode, 'Game.OverseaChat.OverseaChatButtonNode')
    if isNotNull(chatButtonNode) then
        local ChatConstants = import('Game.OverseaChat.ChatConstants')
        chatButtonNode:SetChannelFilter({ChatConstants.Channels.Union})
        chatButtonNode:SetButtonCallback(function()
            CfUtils.DialogOpen(Constants.UITypeIds.OverseaChatMainDialog, {type = ChatConstants.Channels.Union})
        end)
    end
    self:InitBossEnv()
end

function OverseaClubBossMainDialog:AddListener()
    self:RemoveListener()
    self.OnBossDieEvent = Events.AddListener(ClubUtils.EventName.ACTIVITY_BOSS_DIED, Bind(self,self.OnBossDie))
end

function OverseaClubBossMainDialog:RemoveListener()
    if not isNull(self.OnBossDieEvent) then
        Events.RemoveListener(ClubUtils.EventName.ACTIVITY_BOSS_DIED, self.OnBossDieEvent)
        self.OnBossDieEvent = nil
    end
end

function OverseaClubBossMainDialog:InitBossEnv()
    if self.BigBoss then
        local env = CfUtils.GetLuaScr(self.BigBoss,"Game.UI.Club.Boss.Cell.OverseaClubBossInfoNode")
        if not isNull(env) then
            env:InitParams(4)  ---大Boss传入Index为4 方便处理其他逻辑
            env:SetClickCallBack(Bind(self,self.OnBossInfoNodeClick))
            self.bigBossEnv = env
        end
    end

    self.bossEnv = {}
    for i = 1, BossCount do
        local boss = self["SmallBoss"..i]
        if boss then
            local env = CfUtils.GetLuaScr(boss,"Game.UI.Club.Boss.Cell.OverseaClubBossInfoNode")
            if not isNull(env) then
                env:InitParams(i)
                env:SetClickCallBack(Bind(self,self.OnBossInfoNodeClick))
                self.bossEnv[i] = env
            end
        end
    end

end

function OverseaClubBossMainDialog:AddUIClick()
    SetButtonAction(self.BtnChallenge.gameObject,Bind(self,self.OnBtnChallengeClick))
    SetButtonAction(self.BtnTask.gameObject,Bind(self,self.OnBtnTaskClick))
    SetButtonAction(self.BtnBossName.gameObject,Bind(self,self.OnBtnBossNameClick))
end

function OverseaClubBossMainDialog:RefreshPanel()
    KTool.SetActive(self.controller.gameObject,false)
    local clubHomeDojo = ClubUtils.GetClubComp():GetHomeDojo()
    local isInSchedule = clubHomeDojo:IsBossEntryOpening()
    KTool.SetActive(self.CurrentRoundNode.gameObject,isInSchedule)
    KTool.SetActive(self.BtnTask.gameObject,isInSchedule)
    KTool.SetActive(self.TodayTimes.gameObject,isInSchedule)
    KTool.SetActive(self.BtnChallenge.gameObject,isInSchedule)
    KTool.SetActive(self.TextNext.gameObject,not isInSchedule)
    if isInSchedule then
        self:AddListener()
        GameUtils.Request(Interfaces.OverseaClubBossHome,{},function(request,response)
            if checkInt(response.errCode) == 0  then
                local data = response.data
                ClubUtils.GetClubComp():InitialClubBossData(data)
                self.bossDojo = ClubUtils.GetClubComp():GetBossDojo()
                self:RefreshShow()
                KTool.SetActive(self.controller.gameObject,true)
            end
        end)
        self:BindRedPoint()
    else
        local nextScheduleId = clubHomeDojo.nextScheduleId
        if clubHomeDojo.nextScheduleId == 0 then
            printError("社团Boss结束了 不在排期中 也没有下一期的排期 找夜珣！！！！！")
            KTool.SetActive(self.controller.gameObject,false)
            return
        end
        self:RefreshNextScheduleShow(nextScheduleId)
    end
end

function OverseaClubBossMainDialog:RefreshNextScheduleShow(nextScheduleId)
    self:SetTextTimeAndDes(nextScheduleId,true)
    self:RefreshNextRank(true)
    self:RefreshNextReward()
    self:RefreshNextRecord()
    self:RefreshNextBossInfo(nextScheduleId)
    KTool.SetActive(self.controller.gameObject,true)
end

function OverseaClubBossMainDialog:RefreshNextBossInfo(nextScheduleId)
    local data = {}
    for _, bossPassVo in ipairs(ClubUtils.GetPassPassVoByScheduleId(nextScheduleId)) do
        local tempData = {}
        tempData.questId = bossPassVo.id
        tempData.vo      = bossPassVo
        table.insert(data,tempData)
    end

    if table.count(data) <= 0 then
        print("当前排期没有对应的活动Boss数据 请联系策划检查活动关卡表！！！")
        return
    end

    table.sort(data,function(a,b)
        if a.vo.bossTypes == b.vo.bossTypes then
            return a.vo.id < b.vo.id
        else
            return a.vo.bossTypes < b.vo.bossTypes
        end
    end)
    for i, v in pairs(data) do
        ---大Boss
        if v.vo.bossTypes == ClubUtils.BossType.BigBoss then
            self.bigBossData = v
            self.bigBossEnv:RefreshBigBoss(v,true)
        else
            self.bossEnv[i]:RefreshBoss(v,true)
            local arrow = self["ArrowNode"..i]
            if arrow then
                local aniName = "OverseaClubBossMainDialog_Arrow_Lock"
                CfUtils.PlayAnimation(arrow.gameObject,aniName)
            end
        end
    end
    self:SetBigBossName()
end

