function OverseaClubBossMainDialog:SetTextTimeAndDes(scheduleId,isNext)
    local vo = ClubUtils.GetBossActivityVo(scheduleId)
    if next(vo) then
        local zoneText = GameUtils.GetUTCTimeZoneText()
        CfUtils.FillText(self.TextTime,table.concat({string.format('%s%s',vo.startDay, zoneText),"-", string.format('%s%s', vo.endDay, zoneText)}))
    end
    local status = isNext and 2 or 1
    CfUtils.SetUISwitchText(self.TextDesc,status)
    CfUtils.SetUISwitchText(self.TextTime,status)
    CfUtils.SetUISwitchText(self.ImgSymbol,status)
end

function OverseaClubBossMainDialog:OnBossDie()
    GameUtils.Request(Interfaces.OverseaClubBossHome,{},function(request,response)
        if checkInt(response.errCode) == 0  then
            local data = response.data
            ClubUtils.GetClubComp():InitialClubBossData(data)
            self.bossDojo = ClubUtils.GetClubComp():GetBossDojo()
            self:RefreshShow()
        end
    end)
end

