function OverseaClubBossMainDialog:RefreshBossState()
    local bossInfo = self.bossDojo:GetBossInfo()
    for i, v in pairs(bossInfo) do
        local vo = ClubUtils.GetBossPassVo(v.questId)
        if next(vo) then
           v.vo = vo 
        end
    end
    
    table.sort(bossInfo,function(a,b)
        if a.vo.bossTypes == b.vo.bossTypes then
            return a.vo.id < b.vo.id
        else
            return a.vo.bossTypes < b.vo.bossTypes
        end
    end)

    for i, v in pairs(bossInfo) do
        ---大Boss
        if v.vo.bossTypes == ClubUtils.BossType.BigBoss then
            self.bigBossData = v
            self.bigBossEnv:RefreshBigBoss(v)
        else
            self.bossEnv[i]:RefreshBoss(v)
            local arrow = self["ArrowNode"..i]
            if arrow then
                local isLock = checkNumber(v.remainingHp) > 0
                local aniName = isLock and "OverseaClubBossMainDialog_Arrow_Lock" or "OverseaClubBossMainDialog_Arrow_Unlock"
                CfUtils.PlayAnimation(arrow.gameObject,aniName)
            end
        end
    end

    self:RefreshSelect(bossInfo)
end

function OverseaClubBossMainDialog:RefreshSelect(bossInfo)
    local preSelect = nil
    local index = self:GetIndex()
    ---如果Index为4 说明选择的是大Boss 这时要看一下3只小的有没有死 因为刷新轮次的时候 小Boss没死 大Boss是无法被选中的
    if not isNull(index) and checkNumber(index) == 4 then
        local isAllSmallBossDie = self.bossDojo:IsAllSmallBossDie()
        if not isAllSmallBossDie then
            index = nil
        end
    end
    for i, v in pairs(bossInfo) do
        if not isNull(index) then
            preSelect = checkNumber(index)
        else
            if checkNumber(v.remainingHp) > 0 and isNull(preSelect) then
                preSelect = i
            end
        end
    end
    if isNull(preSelect) then
        preSelect = 1
    end

    if preSelect > BossCount then
        self.bigBossEnv:OnBtnNodeClick()
    else
        self.bossEnv[preSelect]:OnBtnNodeClick()
    end
end

function OverseaClubBossMainDialog:GetIndex()
    local initParams = self.controller.Argument.parameters or {}
    local index
    if initParams.extra then
        index = initParams.extra
    end
    return index
end

function OverseaClubBossMainDialog:RefreshBtnState()
    local isUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id4004)
    if not isUnLock then
        self.BtnChallenge.transform:GetComponent(typeof(FontStyleButton)):ResetFontStyle("B17")
        return
    end

    local haveCount  = self.bossDojo:IsHaveTimes()
    local allBossDie = self.bossDojo:IsAllBossDie()

    local style = "B1"
    if not haveCount or allBossDie then
        style = "B17"
    end

    self.BtnChallenge.transform:GetComponent(typeof(FontStyleButton)):ResetFontStyle(style)
end

function OverseaClubBossMainDialog:RefreshTime()
    local scheduleId = self.bossDojo:GetScheduleId()
    self:SetTextTimeAndDes(scheduleId,false)
end

function OverseaClubBossMainDialog:RefreshCount()
    local round = checkNumber(self.bossDojo:GetRound())
    CfUtils.FillText(self.CurCount,round)
end

function OverseaClubBossMainDialog:RefreshLeaveTimes()
    local leaveTime = checkNumber(self.bossDojo:GetLeaveTimes())
    local totalTime = ClubUtils.GetClubComp():GetTotalChallengeTime()
    CfUtils.FillText(self.LeaveTime,string.format("%s/%s",leaveTime,totalTime))
end

function OverseaClubBossMainDialog:RefreshRank()
    local data = self:GetRankData()
    self.rankNodeEnv:Refresh(data)
end

function OverseaClubBossMainDialog:GetRankData()
    local clubHomeDojo = ClubUtils.GetClubComp():GetHomeDojo()
    local clubHeadVo = ClubUtils.GetClubHeadVo(clubHomeDojo.avatar)
    local rank = self.bossDojo:GetClubRank()
    local data = {photoPath = clubHeadVo.photoPath,rank = rank}
    return data
end

function OverseaClubBossMainDialog:RefreshRankReward()
    local rank = self.bossDojo:GetClubRank()
    if rank == 0 then
        self.rewardNodeEnv:Refresh({},false)
    else
        local percentRank = self.bossDojo:GetPercentRank()
        local type = percentRank == 0 and 1 or 2
        local _rank = percentRank == 0 and rank or percentRank
        local reward = ClubUtils.GetRankReward(type,_rank) or {}
        self.rewardNodeEnv:Refresh(reward,true)
    end
end

function OverseaClubBossMainDialog:RefreshRecord()
    self.recordNodeEnv:Refresh(self.bossDojo:GetRecord())
end

function OverseaClubBossMainDialog:OnInitialize()
    return CoWaitDo(function()
        local initParams = CfUtils.DialogSafeParameters(self.controller)
        self:RefreshPanel()
    end)
end

function OverseaClubBossMainDialog:OnFinalize()
    return CoWaitDo(function()
        local initParams = self.controller.Argument.parameters or {}
        initParams.extra = self.curIndex
        self:RemoveListener()
        self:RemoveRedPoint()
        self.controller = nil--luabehaviour 中CSharp对象
        self:Delete()
    end)
end

