function OverseaClubBossMainDialog:OnTipsAction()
    local clubHomeDojo = ClubUtils.GetClubComp():GetHomeDojo()
    local isInSchedule = clubHomeDojo:IsBossEntryOpening()
    local scheduleId
    if isInSchedule then
        scheduleId = self.bossDojo:GetScheduleId()
    else
        scheduleId = clubHomeDojo.nextScheduleId
    end
    if checkNumber(scheduleId) ~= 0 then
        local vo = ClubUtils.GetBossActivityVo(checkNumber(scheduleId))
        if next(vo) then
            CfUtils.ShowModuleToast(vo.ruleId)
        end
    end
end

function OverseaClubBossMainDialog:OnBtnChallengeClick()
    local isUnLock = GameUtils.IsUnlockedBySystemTogId(Constants.SystemToggleIds.Id4004)
    if isUnLock then
        ---当轮次刷新的时候  curBossData可能为空
        if not isNull(self.curBossData) then
            UIModule.OpenDialog({ id = Constants.UITypeIds.UIClubBossChallengeDialog, parameters = { questId = self.curBossData.questId } }, { 
                { id = Constants.UITypeIds.OverseaClubBossMainDialog } 
            })
        end
    else
        GameUtils.Toast(GameUtils.GetUnlockDescrBySystemTogId(Constants.SystemToggleIds.Id4004))
    end
end

function OverseaClubBossMainDialog:OnBtnTaskClick()
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIClubBossTaskDialog, parameters = { systemId = Constants.SystemToggleIds.Id4001} })
end

---这里只显示大Boss的信息 小的不管
function OverseaClubBossMainDialog:OnBtnBossNameClick()
    if isNull(self.bigBossData) then return end
    UIModule.OpenDialog({
        id = Constants.UITypeIds.UIClubBossDetailsDialog,parameters = {questId = self.bigBossData.questId }
    })
end

function OverseaClubBossMainDialog:OnBossInfoNodeClick(i,data)
    if self.curIndex and self.curIndex == i then
        return
    end
    local lastIndex = self.curIndex
    if not isNull(lastIndex) then
        if lastIndex == 4 then
            self.bigBossEnv:DoSelect()
        else
            self.bossEnv[lastIndex]:DoSelect()
        end
    end
    self.curIndex = i
    self.curBossData = data
end

function OverseaClubBossMainDialog:OnBossRankClick()
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIClubBossRankDialog})
end

----click end---------------
function OverseaClubBossMainDialog:SetBigBossName()
    local bossData = QuestConfMgr:GetInstance():GetAllQuestLineupVo(self.bigBossData.questId)
    local bossId
    for i, v in pairs(bossData) do
        for k, j in pairs(v.wave1NpcType) do
            if tonumber(j) == Constants.RoleClass.Boss then
                bossId = v.wave1NpcId[k]
            end
        end
    end
    if not isNull(bossId) then
        local monster = CardConfMgr:GetInstance():GetBaseMonstVo(bossId)
        if not isNull(monster) then
            local skinVo = CardConfMgr:GetInstance():GetCardSkinBySkinId(monster.skinId)
            if not isNull(skinVo) then
                CfUtils.FillText(self.BossName.gameObject,skinVo.name)
            end
        end
    else
        CfUtils.FillText(self.BossName.gameObject,"")
    end
end


return OverseaClubBossMainDialog